/* Reference-led interface: Backhaul Direct Food Bank Network. */
const brandLogo='https://backhauldirect.com/wp-content/uploads/2022/05/BHD-White-Color-Logo.svg';
const channels=['All conversations','General','Food offers & needs','Transportation','Sponsorships'];
let boardChannel='All conversations',boardSearch='';
const demoMessages=[
 {id:'m1',channel:'Food offers & needs',author:'Harvest Grove Foods',role:'Food donor',time:'2026-10-26T09:15:00',text:'We have 20 pallets of fresh produce available in Indianapolis. Two food banks have confirmed their allocations, and the final five-pallet request is awaiting approval. Pickup is Thursday.',link:'F-1042',replies:[{author:'Central Ohio Food Share',time:'2026-10-26T09:32:00',text:'Our seven pallets are confirmed. We can receive Thursday between 8 am and 3 pm.'}]},
 {id:'m2',channel:'Transportation',author:'BHD Operations',role:'Network coordination',time:'2026-10-26T10:05:00',text:'Planning one shared refrigerated route from Indianapolis through Dayton, Columbus and Newark. We still need the final allocation, confirmed transportation funding, and capacity before release.',link:'D-2084',replies:[]},
 {id:'m3',channel:'Sponsorships',author:'Cedar Works',role:'Corporate sponsor',time:'2026-10-26T10:40:00',text:'Our demo matching campaign is open: dollar-for-dollar, up to $500, toward the pantry-staples delivery. Small contributions can help close the transportation gap.',link:'D-2085',replies:[]},
 {id:'m4',channel:'General',author:'BHD Operations',role:'Network coordination',time:'2026-10-26T08:00:00',text:'Welcome to the network board. Share an offer, ask for help with a route, or find a delivery to support. Add a listing or shipment reference so everyone can follow the conversation.',link:'',replies:[]}
];
state.messages??=JSON.parse(JSON.stringify(demoMessages));
const boardAuthor=()=>ops()?'BHD Operations':state.role==='bank'?state.bank:state.role==='carrier'?'Carriers':'Donors & Sponsors';
const stamp=t=>new Date(t).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
function snapshotCell(label,value,sub,p,color=''){return '<button class="snapshot-cell" data-page="'+p+'"><span>'+label+'</span><strong class="'+color+'">'+value+'</strong><small>'+sub+'</small></button>';}
function portalRow(label,role,id='',active=false){return '<button class="portal-row '+(active?'on':'')+'" data-action="enter-portal" data-id="'+esc(role+'|'+id)+'"><span>'+esc(label)+'</span><small>'+(active?'Viewing now':'Enter')+'</small></button>';}
function render(){const pages=[['home','Home'],['food','Food & Needs'],['transport','Transportation'],['sponsor','Fund Food & Delivery'],['board','Message Board'],['impact','Impact'],['network','Network']];document.getElementById('app').innerHTML='<a class="skip" href="#main-content">Skip to content</a><header class="site-header"><div class="header-inner"><button class="brand" data-page="home" aria-label="Backhaul Direct Food Bank Network home"><img src="'+brandLogo+'" alt="Backhaul Direct" width="160" height="42"><span class="brand-divider"></span><span class="brand-title">Food Bank <br>Network</span></button><nav class="mainnav" aria-label="Main navigation">'+pages.map(([p,t])=>'<button data-page="'+p+'" '+(page===p?'aria-current="page"':'')+'>'+t+'</button>').join('')+'</nav><div class="header-tools"><button class="btn primary header-donate" data-action="donate">DONATE</button><div class="rolebox"><label for="role">Demo role</label><select id="role" aria-label="Demo portal role">'+[['bank','Food Banks'],['donor','Donors & Sponsors'],['ops','BHD Operations'],['carrier','Carriers']].map(([v,l])=>'<option value="'+v+'" '+(v===state.role?'selected':'')+'>'+l+'</option>').join('')+'</select></div><button class="header-alert" data-action="activity" aria-label="Activity notifications">'+icon('bell')+'<span>Alerts</span>'+(state.notifications.length?'<b>'+state.notifications.length+'</b>':'')+'</button></div></div><div class="demo-strip"><b>Demonstration prototype.</b> Fictional organizations, routes and figures. No payments are collected. Posts and changes are saved in this browser only.</div></header><main id="main-content" class="content" tabindex="-1">'+({home:homePage,food:foodPage,transport:transportPage,sponsor:sponsorPage,board:boardPage,impact:impactPage,network:networkPage}[page]||homePage)()+'<footer class="footer"><span>Backhaul Direct | Food Bank Network — working concept.</span><span>Demo changes are saved in this browser only.</span>'+btn('About this prototype','tour','ghost')+btn('Reset demo','reset','ghost')+'</footer></main><button class="guide" data-action="tour">'+icon('info')+' 5-minute demo guide</button>';}
function homePage(){const active=state.shipments.filter(s=>!['Delivered','Canceled'].includes(s.status)),done=state.shipments.filter(s=>s.status==='Delivered');return '<section class="hero card"><div><div class="eyebrow">A working concept · powered by Backhaul Direct</div><h1>Food available. Transportation coordinated. <br><em>Delivery funded.</em></h1><p>One network where food banks, donors, transportation providers and corporate sponsors find food, combine orders, fund food purchases, coordinate trucks and fund the delivery.</p></div><div class="actions">'+[['search','food','Find food','Donations, discounted food and shared orders'],['box','offer','Offer food','Post surplus with pallets, weight and pickup date'],['truck','transport','Arrange transportation','Shared routes, return trips and fleet capacity'],['heart','sponsor','Sponsor a delivery','Help food reach its destination'],['box','order','Fund the order','Help buy food for a food bank or community'],['heart','donate','DONATE','Give where it’s needed most']].map(([i,p,l,sub])=>'<button class="action '+(p==='order'?'highlight order-action':['sponsor','donate'].includes(p)?'highlight':'')+'" data-action="quick" data-id="'+p+'"><span class="tile">'+icon(i)+'</span><span><strong>'+l+'</strong><small>'+sub+'</small></span></button>').join('')+'</div></section><h2 class="sec-h">Network snapshot <span class="demo-tag">Demo data</span></h2><div class="snapshot">'+snapshotCell('Open offers & posts',state.items.filter(openFood).length,'on the community board','food')+snapshotCell('Donated pallets available',state.items.filter(f=>openFood(f)&&f.type==='Donation').reduce((n,f)=>n+Math.max(0,f.pallets-held(f)),0),'not yet requested','food')+snapshotCell('Upcoming shipments',active.length,'planned or moving','transport')+snapshotCell('Food & delivery funding gap',money(networkFundingGap()),'open sponsorships','sponsor','amber-text')+snapshotCell('Pounds delivered',num(done.reduce((n,s)=>n+s.receipt.pounds,0)),'completed deliveries','impact','teal-text')+'</div><h2 class="sec-h">Portals <span>— demo role switcher, no accounts</span></h2><div class="portals"><section class="card portal-card"><h3>'+icon('users')+' Food Banks</h3><p>Find food, request quantities, set receiving hours and accept deliveries.</p><div class="portal-list">'+banks.map(b=>portalRow(b,'bank',b,state.role==='bank'&&state.bank===b)).join('')+'</div></section><section class="card portal-card"><h3>'+icon('heart')+' Donors & Sponsors</h3><p>Offer food, approve allocations, and fund food purchases or deliveries.</p><div class="portal-list">'+portalRow('Food donor workspace','donor','',state.role==='donor')+'<button class="portal-row" data-page="sponsor"><span>Corporate sponsorships</span><small>Explore</small></button><button class="portal-row" data-action="recurring"><span>Adopt a recurring delivery</span><small>Get started</small></button></div></section><section class="card portal-card"><h3>'+icon('chart')+' BHD Operations</h3><p>Review offers, plan shared routes, quote, confirm funding and release.</p><div class="portal-list">'+portalRow('BHD Operations','ops','',ops())+'<button class="portal-row" data-page="board"><span>Network message board</span><small>Join the conversation</small></button></div></section></div>'+workspacePanel()+'<h2 class="sec-h">Around the network <span>— recent conversations</span></h2><div class="card recent-board">'+state.messages.slice(0,2).map(m=>'<button data-page="board"><span class="avatar">'+esc(m.author.split(' ').map(x=>x[0]).slice(0,2).join(''))+'</span><span><strong>'+esc(m.author)+'</strong><small>'+esc(m.text)+'</small></span>'+badge(m.channel,'gray')+'</button>').join('')+'</div>';}
function workspacePanel(){const active=state.shipments.filter(s=>!['Delivered','Canceled'].includes(s.status)),allocations=state.items.flatMap(f=>f.allocations.filter(a=>state.role!=='bank'||a.bank===state.bank).map(a=>({...a,food:f}))),profile=state.profiles[state.bank]||{};return '<h2 class="sec-h">Your workspace · '+esc(ops()?'BHD Operations':state.role==='bank'?state.bank:state.role==='carrier'?'Carriers':'Donors & Sponsors')+'</h2><div class="snapshot workspace-stats">'+snapshotCell('Pending requests',allocations.filter(a=>a.status==='Requested').length,'awaiting allocation approval','food')+snapshotCell('Confirmed pallets',allocations.filter(a=>a.status==='Confirmed').reduce((n,a)=>n+a.pallets,0),'allocated across the network','food')+snapshotCell('Active deliveries',active.length,'planning and transportation','transport')+'<button class="snapshot-cell" data-action="'+(state.role==='bank'?'profile':'recurring')+'"><span>'+(state.role==='bank'?'Receiving hours':'Recurring sponsorship')+'</span><strong class="compact">'+(state.role==='bank'?esc(profile.hours||'Mon–Fri, 8 am–3 pm'):'Adopt a route')+'</strong><small>'+(state.role==='bank'?'Edit receiving preferences':'Choose a route and monthly cap')+'</small></button></div><div class="two-col workspace-tables"><section><h3 class="table-title">'+(state.role==='bank'?'My requests':'Allocation requests')+'</h3><div class="card table-wrap"><table><thead><tr><th>Post</th><th>Pallets</th><th>Status</th></tr></thead><tbody>'+allocations.map(a=>'<tr class="clickable" tabindex="0" data-action="food" data-id="'+a.food.id+'"><td><strong>'+esc(a.food.product)+'</strong><small>'+a.food.id+' · '+esc(a.bank)+'</small></td><td>'+a.pallets+'</td><td>'+badge(a.status,a.status==='Confirmed'?'teal':'amber')+'</td></tr>').join('')+'</tbody></table>'+(allocations.length?'':'<div class="empty">No requests yet. Find food to get started.</div>')+'</div></section><section><h3 class="table-title">Upcoming deliveries</h3><div class="card table-wrap"><table><thead><tr><th>Shipment</th><th>Pickup</th><th>Status</th></tr></thead><tbody>'+active.slice(0,3).map(s=>'<tr class="clickable" tabindex="0" data-action="ship" data-id="'+s.id+'"><td><strong>'+s.id+'</strong><small>'+esc(s.title)+'</small></td><td>'+date(s.date)+'</td><td>'+status(s)+'</td></tr>').join('')+'</tbody></table></div></section></div>';}
function foodCard(f){return '<article class="food-card" role="button" tabindex="0" data-action="food" data-id="'+f.id+'" aria-label="Open '+esc(f.title)+'"><div class="food-thumb '+f.band+'">'+icon(f.icon)+'</div><div class="food-body">'+badge(openFood(f)?f.type:'Closed',f.type==='Donation'?'teal':f.type==='Food needed'?'amber':'gray')+'<h3>'+esc(f.title)+'</h3><div class="org">'+esc(f.org)+' · '+esc(f.city)+' · '+f.id+'</div><div class="food-data">'+f.pallets+' pallets · '+num(f.pounds)+' lb · '+f.temp+'</div><div class="food-meta">Available until '+date(f.deadline)+'</div><div class="progress"><span style="width:'+Math.min(100,held(f)/(f.pallets||1)*100)+'%"></span></div><small class="muted">'+Math.max(0,f.pallets-held(f))+' of '+f.pallets+' pallets remaining'+(f.price?' · '+money(f.price)+'/pallet':'')+'</small></div></article>';}
function deliveryFundingPage(){const active=state.shipments.filter(s=>s.status==='Planning'&&!s.review);return head('','Sponsor a Delivery','Help move food to the people who need it. This option covers transportation; use Fund the order to support a food purchase.')+'<div class="snapshot sponsor-stats">'+snapshotCell('Deliveries needing funding',active.filter(s=>available(s)>0).length,'open for sponsorship','sponsor')+snapshotCell('Remaining transportation gap',money(active.reduce((n,s)=>n+available(s),0)),'available to pledge','sponsor','amber-text')+snapshotCell('Pledged, awaiting confirmation',money(active.reduce((n,s)=>n+pending(s),0)),'pending pledges','sponsor')+snapshotCell('Confirmed funding',money(active.reduce((n,s)=>n+confirmed(s),0)),'applied to active deliveries','sponsor','teal-text')+'</div><div class="section-head"><span class="small muted">Deliveries open for sponsorship</span><span class="small muted">Choose your sponsor name in the pledge form</span></div><div class="sponsor-grid">'+(active.map(s=>'<article class="sponsor-card"><div class="sponsor-top"><span class="small muted">'+s.id+' · '+s.temp+'</span>'+status(s)+'</div><h3>'+esc(s.title)+'</h3><p>Food '+(item(s.itemId)?.type==='Donation'?'donated':'supplied')+' by <strong>'+esc(item(s.itemId)?.org||s.supplier||'Network supplier')+'</strong> · '+s.pallets+' pallets · '+num(s.pounds)+' lb</p><div class="route-chips">'+s.route.map((r,i)=>(i?'<span>→</span>':'')+'<b>'+esc(r)+'</b>').join('')+'</div><div class="delivery-facts"><div><small>Pickup deadline</small><strong>'+date(s.date)+'</strong></div><div><small>Transportation target</small><strong>'+money(target(s))+'</strong></div><div><small>Open to sponsor</small><strong class="amber-text">'+money(available(s))+'</strong></div></div>'+bar(s)+'<div class="note">Your sponsorship funds <strong>transportation only</strong>. The quote includes transportation, handling and Backhaul Direct coordination.</div><div class="sponsor-actions">'+btn('Sponsor this delivery','pledge','primary',s.id)+btn('Details','ship','',s.id)+'</div></article>').join('')||'<div class="empty">No deliveries currently open to sponsorship.</div>')+'</div><h2 class="sec-h">Support a recurring route or matching campaign</h2><div class="two-col"><section class="card pad extra">'+icon('calendar')+'<div><h3>Adopt a recurring delivery</h3><p>Choose a community and a monthly cap. Agree the schedule and cost before making a live commitment.</p>'+btn('Explore route sponsorship','recurring','primary')+'</div></section><section class="card pad extra">'+icon('heart')+'<div><h3>Make a contribution. Double its reach.</h3><p>Cedar Works offers a demo dollar-for-dollar match up to $500 toward the pantry-staples delivery.</p>'+btn('Join the matching campaign','match','',state.match.shipment)+'</div></section></div>';}
function messageLink(id){if(!id)return '';const f=item(id),s=ship(id);return f?btn(icon('box')+' '+id+' · '+esc(f.product),'food','sm message-link',id):s?btn(icon('truck')+' '+id+' · '+esc(s.title),'ship','sm message-link',id):order(id)?btn(icon('box')+' '+id+' · '+esc(order(id).title),'order-detail','sm message-link',id):'';}
function boardPage(){const list=state.messages.filter(m=>(boardChannel==='All conversations'||m.channel===boardChannel)&&(m.text+' '+m.author+' '+m.channel+' '+m.replies.map(r=>r.text).join(' ')).toLowerCase().includes(boardSearch.toLowerCase()));return head('','Message Board','A place to share offers, coordinate deliveries, ask questions, and keep the network connected.')+'<div class="board-layout"><aside class="card channel-panel"><h2 class="sec-h">Channels</h2>'+channels.map(c=>'<button class="channel '+(c===boardChannel?'active':'')+'" data-action="channel" data-id="'+c+'"><span># '+c+'</span><small>'+state.messages.filter(m=>c==='All conversations'||m.channel===c).length+'</small></button>').join('')+'<div class="board-tip"><strong>Keep the details together.</strong><p>Link a food listing or shipment so others can see the quantities, route and funding status.</p></div></aside><div class="board-feed"><section class="card composer"><div class="composer-heading"><span class="avatar">'+esc(boardAuthor().split(' ').map(x=>x[0]).slice(0,2).join(''))+'</span><div><strong>Start a conversation</strong><small>Posting as '+esc(boardAuthor())+'</small></div></div><form data-board-form="message"><label class="sr-only" for="message-text">Your message</label><textarea id="message-text" name="message" class="input" rows="3" maxlength="2000" placeholder="Share an update, offer food, or ask the network…" required></textarea><div class="composer-controls"><select name="channel" class="input" aria-label="Post channel">'+channels.slice(1).map(c=>'<option '+(c===boardChannel?'selected':'')+'>'+c+'</option>').join('')+'</select><select name="link" class="input" aria-label="Link a food listing or shipment"><option value="">Link a listing or delivery (optional)</option>'+state.items.map(f=>'<option value="'+f.id+'">'+f.id+' · '+esc(f.product)+'</option>').join('')+state.shipments.map(s=>'<option value="'+s.id+'">'+s.id+' · '+esc(s.title)+'</option>').join('')+state.orders.map(o=>'<option value="'+o.id+'">'+o.id+' · '+esc(o.title)+'</option>').join('')+'</select><button class="btn primary" type="submit">Post message '+icon('arrow')+'</button></div><p class="small muted">Demo board · Posts and replies are saved in this browser only.</p></form></section><div class="board-toolbar"><h2>'+esc(boardChannel)+'</h2><form data-board-form="search" class="board-search"><input name="query" class="input" aria-label="Search conversations" placeholder="Search conversations" value="'+esc(boardSearch)+'"><button class="btn" aria-label="Search message board">'+icon('search')+'</button></form></div><div class="messages">'+(list.map(m=>'<article class="card message"><div class="message-header"><span class="avatar">'+esc(m.author.split(' ').map(x=>x[0]).slice(0,2).join(''))+'</span><div><strong>'+esc(m.author)+'</strong><small>'+esc(m.role)+' · '+stamp(m.time)+'</small></div>'+badge(m.channel,'gray')+'</div><p class="message-text">'+esc(m.text)+'</p>'+messageLink(m.link)+'<details class="thread" '+(m.replies.length?'open':'')+'><summary>'+icon('users')+' '+m.replies.length+' '+(m.replies.length===1?'reply':'replies')+' · Join the conversation</summary><div class="replies">'+m.replies.map(r=>'<div class="reply"><div><strong>'+esc(r.author)+'</strong><small>'+stamp(r.time)+'</small></div><p>'+esc(r.text)+'</p></div>').join('')+'</div><form data-board-form="reply" data-message-id="'+m.id+'" class="reply-form"><label class="sr-only" for="reply-'+m.id+'">Reply to '+esc(m.author)+'</label><input id="reply-'+m.id+'" name="reply" class="input" maxlength="1000" required placeholder="Write a reply…"><button class="btn" type="submit">Reply</button></form></details></article>').join('')||'<div class="empty">No conversations match. Try another channel or search.</div>')+'</div></div></div>';}
document.addEventListener('click',e=>{const n=e.target.closest('[data-action]');if(!n)return;if(n.dataset.action==='enter-portal'){const [role,bank]=n.dataset.id.split('|');state.role=role;if(bank)state.bank=bank;save();render();toast('Viewing '+boardAuthor()+'.');}if(n.dataset.action==='channel'){boardChannel=n.dataset.id;boardSearch='';render();}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.boardForm)return;e.preventDefault();const f=new FormData(form),kind=form.dataset.boardForm;if(kind==='search'){boardSearch=String(f.get('query')||'').trim();render();return;}if(kind==='message'){const text=String(f.get('message')||'').trim();if(!text)return;const channel=String(f.get('channel'));state.messages.unshift({id:'m'+Date.now(),channel,author:boardAuthor(),role:ops()?'Network coordination':state.role==='bank'?'Food bank':'Donor / sponsor',time:new Date().toISOString(),text:text.slice(0,2000),link:String(f.get('link')||''),replies:[]});boardChannel=channel;boardSearch='';}else{const m=state.messages.find(x=>x.id===form.dataset.messageId),text=String(f.get('reply')||'').trim();if(!m||!text)return;m.replies.push({author:boardAuthor(),time:new Date().toISOString(),text:text.slice(0,1000)});}save();render();toast(kind==='message'?'Message posted to the demo board.':'Reply added to the demo board.');});
const originalSeed=seed;seed=()=>({...originalSeed(),messages:JSON.parse(JSON.stringify(demoMessages))});
// Initialized after order funding and leaderboard support.
